import pandas as pd
import numpy as np

# Load datasets
df = pd.read_csv('chunks_csv/moran_local_2021_energy.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate median energy for high/low classification
median_energy = df['Energy_value'].median()
print(f"Median energy: {median_energy}")

# Classify boroughs as high (1) or low (0) energy
df['energy_class'] = (df['Energy_value'] > median_energy).astype(int)

# Function to check if a borough is hotspot (HH) or coldspot (LL)
def classify_spot(borough_name, borough_energy, neighbors):
    neighbor_energies = []
    for neighbor in neighbors:
        neighbor_energy = df.loc[df['borough'] == neighbor, 'Energy_value'].values
        if len(neighbor_energy) > 0:
            neighbor_energies.append(neighbor_energy[0])

    if len(neighbor_energies) == 0:
        return None  # No neighbors to compare

    neighbor_median = np.median(neighbor_energies)
    borough_class = 1 if borough_energy > median_energy else 0
    neighbors_class = 1 if neighbor_median > median_energy else 0

    if borough_class == 1 and neighbors_class == 1:
        return 'HH'
    elif borough_class == 0 and neighbors_class == 0:
        return 'LL'
    else:
        return None

# Process each borough
results = []
for _, row in df.iterrows():
    borough = row['borough']
    energy = row['Energy_value']
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()

    classification = classify_spot(borough, energy, neighbors)
    if classification:
        results.append((borough, classification, energy))

# Filter significant spots (require at least 2 neighbors matching)
final_spots = []
for borough, classification, energy in results:
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    neighbor_energies = []
    for neighbor in neighbors:
        neighbor_energy = df.loc[df['borough'] == neighbor, 'Energy_value'].values
        if len(neighbor_energy) > 0:
            neighbor_energies.append(neighbor_energy[0])

    if len(neighbor_energies) < 2:
        continue  # Need at least 2 neighbors for meaningful pattern

    if classification == 'HH':
        if all(e > median_energy for e in neighbor_energies):
            final_spots.append((borough, 'HH', energy))
    elif classification == 'LL':
        if all(e <= median_energy for e in neighbor_energies):
            final_spots.append((borough, 'LL', energy))

# Prepare final answer
if final_spots:
    answer_parts = []
    for spot in final_spots:
        answer_parts.append(f"{spot[0]} ({spot[1]}, energy={spot[2]:.1f})")
    print("FINAL ANSWER:", ", ".join(answer_parts))
else:
    print("FINAL ANSWER: none")
